def send_email(send_email_address, receive_email_address, smtp_code, email_subject='', email_info='', attachment_path=''):
    """
    :param send_email_address: 发送方的邮箱地址
    :type send_email_address: str
    :param receive_email_address: 接收方的邮箱地址
    :type receive_email_address: str
    :param smtp_code: 邮箱smtp授权码
    :type smtp_code: str
    :param email_subject: 邮件主题
    :type email_subject: str
    :param email_info: 发送内容
    :type email_info: str
    :param attachment_path: 附件路径
    :type attachment_path: str
    :return: 包含error_no、error_info的信息
    :rtype: dict
    """
    return_info = {'error_no': -1, 'error_info': ''}
    try:
        msg = MIMEMultipart()
        body = MIMEText(email_info, 'plain', 'utf-8')
        msg.attach(body)
        if attachment_path != '':
            if SEND_EMAIL_FILE_PERMISSION == '1':
                return_info['error_info'] = '系统配置不允许发送邮件附件, 本次发送过程附件将不会被发送'
                return return_info
            else:
                attachment_size = float(round(os.path.getsize(attachment_path) / 1024 / 1024, 2))
                if attachment_size >= QQ_UPLOAD_FILE_LIMIT:
                    return_info['error_info'] = f'邮件附件上传文件大小为{attachment_size!s}MB，超过系统限制{QQ_UPLOAD_FILE_LIMIT!s}MB。'
                    return return_info
                else:
                    attachment = MIMEBase('application', 'octet-stream')
                    attachment.set_payload(open(attachment_path, 'rb').read())
                    encoders.encode_base64(attachment)
                    attachment.add_header('Content-Disposition', 'attachment', filename=attachment_path.split('/')[-1])
                    msg.attach(attachment)
                    msg['From'] = format_addr('<%s>' % send_email_address)
                    msg['To'] = format_addr('<%s>' % receive_email_address)
                    msg['Subject'] = Header(email_subject, 'utf-8').encode()
                    server = smtplib.SMTP_SSL(host=QQ_SERVER, port=465)
                    server.ehlo(QQ_SERVER)
                    server.login(send_email_address, smtp_code)
                    server.sendmail(send_email_address, to_addrs=receive_email_address, msg=msg.as_string())
                    server.quit()
                    return_info['error_no'] = 0
                    return return_info
    except BaseException:
        error_info = get_traceback_message()
        strategy_log.error('异常信息: %s' % error_info)
        return_info['error_info'] = error_info
        return return_info
def send_error_email(email_address, smtp_code, email_subject, email_info):
    """
    发送报错邮件
    :param email_address: 邮箱地址
    :type email_address: str
    :param smtp_code: 邮箱smtp授权码
    :type smtp_code: str
    :param email_subject: 邮件主题
    :type email_subject: str
    :param email_info: 邮件内容
    :type email_info: str
    :return: 包含error_no、error_info的信息
    :rtype: dict
    """
    return send_email(email_address, email_address, smtp_code, email_subject, email_info)
